inline proc make_default_step_factory(k: real, dt: real, dx: real)
{
 return proc(left: future<[] real>, middle: future<[] real>, right: future<[] real>): future<[] real>
 {
 var coeff = k * dt / (dx * dx);

 return future (l: [] real, m: [] real, r: [] real): [] real
 {
 var N = m.size;
 assert(N >= 2);

 var next: [0..<N] real;

 for j in 1..<N-1
 next[j] = m[j] + coeff * (m[j - 1] - 2.0 * m[j] + m[j + 1]);

 next[0] = m[0] + coeff * (l[l.size-1] - 2.0 * m[0] + m[1]);
 next[N - 1] = m[N - 1] +
 coeff * (m[N - 2] - 2.0 * m[N - 1] + r[0]);

 return next;
 }(left, middle, right);
 };
}
