// stateless SplitMix64 hash to make RNG reproducible across runs
proc splitmix64(x: uint): uint
{
 x += 0x9E3779B97F4A7C15;
 x = (x ^ (x >> 30)) * 0xBF58476D1CE4E5B9;
 x = (x ^ (x >> 27)) * 0x94D049BB133111EB;
 x ^= (x >> 31);
 return x;
}

proc sample_unit_interval(index: uint, seed: uint): real
{
 var value = splitmix64(index + seed);
 return (value >> 11) / (1.0 : real(64));
}

